<div class="grid gap-5 md:grid-cols-2"><x-ui.select name="source_type" label="Type de source" :value="$item->source_type" :options="['ticket'=>'Ticket','label'=>'Étiquette','barcode'=>'Code-barres','qr'=>'QR code']" required/><x-ui.select name="status" label="Statut" :value="$item->status ?: 'pending'" :options="['pending'=>'En attente','processing'=>'Traitement','completed'=>'Terminé','failed'=>'Échec']" required/><x-ui.input name="image_path" label="Chemin de l’image" :value="$item->image_path"/><x-ui.input name="confidence" label="Confiance (%)" type="number" :value="$item->confidence" min="0" max="100" step="0.01"/><x-ui.input name="scanned_at" label="Date du scan" type="datetime-local" :value="optional($item->scanned_at)->format('Y-m-d\TH:i')"/><div class="md:col-span-2"><x-ui.textarea name="raw_text" label="Texte OCR extrait" :value="$item->raw_text" rows="6"/></div></div>
